CREATE TABLE IF NOT EXISTS app_users(id VARCHAR(36) PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,name VARCHAR(80) NOT NULL,password_hash VARCHAR(100) NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS app_sessions(token_hash VARCHAR(64) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id VARCHAR(60) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,title VARCHAR(255) NOT NULL,file_name VARCHAR(255) NOT NULL,stored_name VARCHAR(100),source_kind VARCHAR(20) NOT NULL,doc_status VARCHAR(20) NOT NULL,pages INT DEFAULT 0,chunks INT DEFAULT 0,byte_size BIGINT DEFAULT 0,created_at VARCHAR(40) NOT NULL,error_message VARCHAR(500));
CREATE TABLE IF NOT EXISTS conversations(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,title VARCHAR(255) NOT NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id VARCHAR(36) PRIMARY KEY,conversation_id VARCHAR(36) NOT NULL,user_id VARCHAR(36) NOT NULL,role_name VARCHAR(20) NOT NULL,content LONGTEXT NOT NULL,msg_status VARCHAR(20) NOT NULL,citations_json LONGTEXT,trace_json LONGTEXT,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS agent_runs(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,conversation_id VARCHAR(36) NOT NULL,message_id VARCHAR(36) NOT NULL,run_status VARCHAR(20) NOT NULL,answer_mode VARCHAR(20) NOT NULL,question TEXT NOT NULL,answer LONGTEXT,citations_json LONGTEXT,trace_json LONGTEXT,error_message VARCHAR(500),latency_ms BIGINT DEFAULT 0,idempotency_key VARCHAR(100) NOT NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL,request_hash VARCHAR(64) NOT NULL,UNIQUE(user_id,idempotency_key));
